/* Read only. Two queries: run each on its own (select the line, then Run). The first is the pre-flight, the second lists the storage policies as they are now: keep a copy. */
select pg_has_role(current_user, (select relowner from pg_class where oid = 'storage.objects'::regclass), 'member') as can_manage_storage_policies, to_regclass('public.email_change_codes') is not null as has_email_codes, to_regclass('public.email_flows') is not null as has_email_flows, to_regclass('public.digital_assets') is not null as has_assets, to_regclass('public.product_bundles') is not null as has_bundles, (select count(*) from public.products where archived is true and status = 'published') as products_it_rewrites, to_regclass('public.ledger_events') is not null and to_regclass('public.analytics_events') is not null and to_regclass('public.email_logs') is not null as has_ledger_events_email_logs, exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'subscribers' and column_name = 'status') as has_subscriber_status, to_regclass('public.product_variants') is not null and to_regclass('public.product_variant_files') is not null and to_regclass('public.reviews') is not null and to_regclass('public.courses') is not null as has_variants_reviews_courses, to_regclass('public.theme_agent_activity') is not null as has_agent_log, (select rolbypassrls from pg_roles where rolname = current_user) as editor_bypasses_rls, exists (select 1 from information_schema.columns where table_schema = 'storage' and table_name = 'objects' and column_name = 'owner_id') as storage_has_owner_id;
select policyname, cmd, roles, qual, with_check from pg_policies where schemaname = 'storage' and tablename = 'objects' order by policyname;
